export interface MlbStatsRatesBlock {
  /** Provenance tag, e.g. 'player_game_stats_sum' (own box scores, summed to team level). */
  source?: string | null;
  /** Which rolling window this block covers: 'l5' (see `window_size` for the fixed game count) or 'season' (an intentionally variable-length window — see `games` for how many games it actually covers for this team). */
  window?: string | null;
  /** Fixed sample depth for this window, only present when the window has one (e.g. 5 for 'l5'). Omitted for 'season' — use `games` instead. */
  window_size?: number | null;
  /** Games with box-score data included in this aggregate. */
  games?: number;
  /** Avg. team at-bats per game. */
  at_bats?: number | null;
  /** Avg. team hits per game. */
  hits?: number | null;
  /** Avg. team runs scored per game. */
  runs?: number | null;
  /** Avg. team home runs per game. */
  home_runs?: number | null;
  /** Avg. team walks (bases on balls) drawn per game. */
  walks?: number | null;
  /** Avg. team batter strikeouts per game. */
  strikeouts?: number | null;
  /** Avg. team doubles per game. */
  doubles?: number | null;
  /** Avg. team triples per game. */
  triples?: number | null;
  /** Avg. team runs batted in per game. */
  rbi?: number | null;
  /** Avg. team hit-by-pitch plate appearances per game. */
  hit_by_pitch?: number | null;
  /** Avg. team stolen bases per game. */
  stolen_bases?: number | null;
  /** Avg. team total bases per game (H + 2B + 2·3B + 3·HR). Null when any TB component (hits/doubles/triples/home_runs) is missing from the window. */
  total_bases?: number | null;
  /** Team batting average across the window: total hits / total at-bats (not an average of per-game averages). */
  batting_avg?: number | null;
  /** Team on-base percentage across the window: (H + BB + HBP) / (AB + BB + HBP). Sacrifice flies are not in Path A box ingest, so SF is omitted from the denominator (slightly higher than official OBP when SF > 0). */
  obp?: number | null;
  /** Team slugging percentage across the window: total bases / total at-bats. */
  slg?: number | null;
  /** Team OPS across the window: obp + slg (same SF caveat as `obp`). */
  ops?: number | null;
  /** Avg. team outs recorded per game. The additive unit behind innings_pitched/ERA/WHIP/K9/BB9. */
  outs?: number | null;
  /** Avg. team innings pitched per game as true innings (total outs ÷ 3 ÷ games). Not baseball notation — see starting_pitcher.innings_pitched for N.outs display. */
  innings_pitched?: number | null;
  /** Avg. team earned runs allowed per game. */
  earned_runs?: number | null;
  /** Avg. team hits allowed per game. */
  hits_allowed?: number | null;
  /** Avg. team walks allowed per game. */
  walks_allowed?: number | null;
  /** Avg. team pitcher strikeouts recorded per game. */
  strikeouts_pitched?: number | null;
  /** Avg. team home runs allowed per game. */
  home_runs_allowed?: number | null;
  /** Team ERA across the window: (total earned runs × 9) / (total outs ÷ 3). Uses outs math — baseball IP notation (.1/.2 = outs) is not additive. */
  era?: number | null;
  /** Team WHIP across the window: (total walks allowed + total hits allowed) / (total outs ÷ 3). */
  whip?: number | null;
  /** Team strikeouts per 9 innings across the window: (total pitcher strikeouts × 9) / (total outs ÷ 3). */
  k9?: number | null;
  /** Team walks allowed per 9 innings across the window: (total walks allowed × 9) / (total outs ÷ 3). */
  bb9?: number | null;
  /** Per-field sample size, keyed by the raw box-score slugs summed into the fields above (at_bats, hits, runs, home_runs, walks, strikeouts, doubles, triples, rbi, hit_by_pitch, stolen_bases, outs, innings_pitched, earned_runs, hits_allowed, walks_allowed, strikeouts_pitched, home_runs_allowed). `games` is how many games are in this window overall, but an individual field can have a smaller count when a box score omits that stat. Derived ratios (batting_avg/obp/slg/ops/total_bases/era/whip/k9/bb9) are NOT keys here — they are computed from the sum of their raw component slugs above, so check the relevant component slug(s) instead (e.g. `hits` + `at_bats` for `batting_avg`). */
  field_games?: Record<string, unknown>;
  [key: string]: unknown;
}

